"C:\\Program Files\\PowerShell\\7\\pwsh.exe" -Command '$puzzleScripts = '"'trace_puzzle','trace_second','trace_third','trace_graph','trace_texture','trace_fourth','trace_graphtex','trace_direction','trace_graphdir','trace_merge','trace_beam','trace_beamflat','trace_phase','trace_beamphase','trace_gates','trace_flow','trace_dense','trace_compare','trace_repair','trace_densephase','trace_ensemble','trace_densestem'
